// debours.js — L'ONGLET « 💶 DÉBOURS » D'UNE AFFAIRE (19/10/2026, lot DB). Ethan : « créer tout l'aspect débours : par affaire, pouvoir faire des bons de commande
// rattachés à une affaire, que ça rentre les dépenses, toutes les heures des gars pointées par chantier × notre coût horaire, enlever au facturé […] tout un onglet
// bien vaste, bien pro, bien propre ». Facturé (situations mensuelles a.fact + situations déposées / payées de la facturation) − débours (main-d'œuvre, achats = bons
// de commande, notes de frais validées ramenées en HT, sous-traitance, location, autres) = marge ; reste à facturer = marché − facturé.
// HEURES : LE calcul de la navette (espace.js → navette.js : heures du jour de chaque pointage, semaine lundi → samedi, le dimanche n'entre pas dans la navette) relu par
// espaceNavette — jamais un calcul parallèle. COÛT HORAIRE : posteRate (prix.js) du poste de la personne dans la base de prix, ou le taux saisi pour l'affaire
// (a.debours.taux[poste]) quand la base ne le donne pas (chef de chantier, aide…). Chantier partagé (lot MU) : seulement la part de l'affaire (soudures du tracé, ou %
// saisi dans a.debours.part[chantier]). Données OPTIONNELLES dans l'affaire : a.debours = {taux:{poste:€/h}, tva:20, lignes:[{id,date,type,lib,fournisseur,montant,…}],
// part:{chantier:%}} (registre « affaire », droits existants — aucun SQL) ; un bon marqué facturé garde son montant de facture sur la commande (c.facture).
// Accroches : affaires.js (onglet après Facturation, vue d'ensemble du Reporting), commandes.js (bons liés, « ‹ Affaire ») ; module branché sur l'espace (espaceExt :
// champs data-xin="db|…", actions data-act="x" data-v="db|…", annuaire des personnes avec leur poste). Calcul par affaire mémorisé (cache invalidé quand les
// pointages, les chantiers liés ou le jour changent), pas de recalcul à chaque rendu.
import {regAll,regGet,regSet} from './reg.js';
import {affGet,affSet,affAll,affState,affOpen} from './affaires.js';
import {espaceState,espaceNavette,espaceExt,espaceToday} from './espace.js';
import {posteRate} from './prix.js';
import {prixBase} from './chiffrage.js';
import {POSTES} from './acces.js';
import {addDay,mondayOf,r2} from './compteurs.js';
import {makeXlsx} from './xlsx.js';
let A=null;let CMD=null; /* CMD : fonctions de commandes.js remises par dbCmdBind (commandes.js importe affaires.js au chargement : pas d'import croisé d'ici) */
export function initDebours(api){A=api;css();try{espaceExt(MOD);}catch(e){console.warn('débours : module',e);}}
export function dbCmdBind(o){CMD=o||null;}
export function dbGoAffaire(num){affOpen(num,'debours');DS.cy=null;try{if(EC&&EC.api&&EC.api.homeTab)EC.api.homeTab('commerce');else if(EC&&EC.render)EC.render();}catch(e){console.warn(e);}} /* commandes.js : « ‹ Affaire » depuis un bon rattaché → l'onglet Débours */
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nb=(x,d)=>{x=+x||0;return x.toLocaleString('fr-FR',{maximumFractionDigits:d===undefined?0:d,minimumFractionDigits:d===undefined?0:d});};
const eur=x=>nb(x)+' €';
const eur2=x=>nb(x,2)+' €';
const nbx=(x,d)=>(+x||0).toLocaleString('fr-FR',{maximumFractionDigits:d===undefined?1:d}); /* décimales seulement si besoin (parts, heures) */
const hh=x=>{x=r2(x);return (Number.isInteger(x)?String(x):x.toLocaleString('fr-FR',{maximumFractionDigits:2}))+' h';};
const pct=(x,t)=>t>0?nb(100*x/t,1)+' %':'—';
const dFR=x=>x?new Date(String(x).length<=10?x+'T12:00:00':x).toLocaleDateString('fr-FR'):'';
const MOIS=['Janv','Fév','Mars','Avr','Mai','Juin','Juil','Août','Sept','Oct','Nov','Déc'];
const MOIS_L=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const ymTxt=ym=>ym?MOIS_L[+String(ym).slice(5,7)-1]+' '+String(ym).slice(0,4):'';
const ymAdd=(ym,n)=>{const [y,m]=String(ym).split('-').map(Number);const k=y*12+(m-1)+n;return Math.floor(k/12)+'-'+String((k%12)+1).padStart(2,'0');};
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const today=()=>{try{return espaceToday();}catch(e){return new Date().toISOString().slice(0,10);}};
export const DB_TYPES=[['st','Sous-traitance'],['loc','Location'],['autre','Autre dépense']];
const POSTE_BASE={soudeur:'Soudeur',tuyauteur:'Tuyauteur',manchonneur:'Manchonneur',chauffeur_engin:'Chauffeur',activites_specifiques:'Opérations spécifiques'}; /* poste de l'annuaire → poste de la base de prix (posteRate cherche par début de libellé) */
/* ── état de l'onglet (par appareil, le temps de la session) ── */
const DS={per:'tout',y:new Date().getFullYear(),m:new Date().toISOString().slice(0,7),cy:null,open:{mo:true,ach:true,nf:true,dep:true},ov:false};
export const dbState=()=>DS;
/* ── module branché sur l'espace : personnes (id, poste), actions, champs ── */
let EC=null; /* dernier contexte de l'espace (annuaire DATA.personnes avec clé + poste, api de l'espace) */
const cap=ctx=>{if(ctx)EC=ctx;try{if(typeof window!=='undefined'&&window.TRACE&&!window.TRACE.debours)window.TRACE.debours=dbTestApi();}catch(e){}};
const MOD={id:'db',gate(me,ctx){cap(ctx);return null;},tasks(me,ctx){cap(ctx);return [];},moiSubs(me,ctx){cap(ctx);return [];},act(v,el,me,ctx){cap(ctx);dbAct(v,el,me,ctx);},input(champ,el,me,ctx,type){cap(ctx);if(type==='change')dbInput(champ,el,me,ctx);}};
function peopleIdx(){const m=new Map();const add=(id,name,poste)=>{if(id&&!m.has(id))m.set(id,{id,name:name||id,poste:poste||'autre'});};
  if(EC&&Array.isArray(EC.people))EC.people.forEach(p=>add(p.id,((p.prenom||'')+' '+(p.nom||'')).trim(),p.poste));
  if(!m.size&&EC&&EC.api){try{const L=(EC.api.accounts&&EC.api.accounts())||(EC.api.personas&&EC.api.personas())||[];L.forEach(a=>add(((a.email||'').toLowerCase()||String(a.id||'')),a.name,a.poste));}catch(e){}}
  return m;}
const unk=id=>({id,name:String(id||'?').replace(/^l:/,'').split('@')[0],poste:'?'});
const posteLab=p=>POSTES[p]||(p==='?'?'poste inconnu':p||'');
/* ── données de l'affaire ── */
const D=a=>(a&&a.debours&&typeof a.debours==='object')?a.debours:{};
const tvaOf=a=>{const v=D(a).tva;return v===undefined||v===null||v===''||!isFinite(+v)||+v<0?20:+v;};
const lignesOf=a=>(D(a).lignes||[]).filter(l=>l&&!l.deleted&&l.id);
function dbSave(a,patch){const cur=affGet(a.num)||a;const d=Object.assign({},D(cur),patch);affSet(a.num,{debours:d});}
export function dbHasData(a){if(!a)return false;const d=D(a);return !!((d.lignes||[]).some(l=>l&&!l.deleted)||Object.keys(d.taux||{}).length||bonsAffaire(a).length);}
/* coût horaire d'un poste : taux saisi pour l'affaire, sinon la base de prix (posteRate = taux + frais généraux + sinistre), sinon 0 (à renseigner) */
export function tauxPoste(a,poste){const T=D(a).taux||{};const v=T[poste];if(v!==undefined&&v!==null&&v!==''&&isFinite(+v)&&+v>0)return {h:+v,src:'affaire'};
  const b=prixBase();if(b&&poste&&poste!=='?'){for(const code of [POSTE_BASE[poste],POSTES[poste]]){if(!code)continue;let r=0;try{r=posteRate(b,code);}catch(e){r=0;}if(r>0)return {h:r2(r),src:'base'};}}return {h:0,src:null};}
/* ── HEURES : les lignes de la navette (espace.js → navette.js), par personne et par mois de navette, puis par jour pointé ── */
const HCACHE=new Map();
const navYm=d=>addDay(mondayOf(d),3).slice(0,7); /* une semaine compte dans le mois de son jeudi (règle de la navette) */
const ptSig=x=>{const ev=x.events||[];const l=ev[ev.length-1]||{};return x.p+'|'+x.d+'|'+(x.site||'')+'|'+(x.status||'')+'|'+((x.val||[]).length)+'|'+ev.length+(l.t||'')+(l.at||'');};
export function heuresAffaire(a){const sites=new Set(a.sites||[]);const PT=((espaceState()||{}).pointages||[]).filter(x=>x&&x.d&&sites.has(x.site));const sig=today()+'|'+[...sites].join(',')+'|'+PT.map(ptSig).join(';');
  const c=HCACHE.get(a.num);if(c&&c.sig===sig)return c;
  const NAV={};const navOf=(p,ym)=>{const k=p+'|'+ym;if(!(k in NAV)){let m={};try{const R=espaceNavette(p,ym);((R&&R.N&&R.N.lines)||[]).forEach(L=>{if(L.kind==='day')m[L.d]=+L.hours||0;else if(L.kind==='sat')m[L.d]=+L.satHours||0;});}catch(e){console.warn('débours : navette',p,ym,e);m=null;}NAV[k]=m;}return NAV[k];};
  const rows=[];PT.forEach(x=>{const wd=new Date(x.d+'T12:00:00').getDay();if(wd===0)return; /* dimanche : hors semaine de navette (lundi → samedi), comme la paie */const m=navOf(x.p,navYm(x.d));if(!m||m[x.d]===undefined)return;const h=r2(m[x.d]);if(!(h>0))return;rows.push({p:x.p,d:x.d,ym:x.d.slice(0,7),site:x.site,h,ok:x.status==='valide'||(x.val||[]).length>0});});
  const out={sig,rows};HCACHE.set(a.num,out);if(HCACHE.size>40)HCACHE.delete(HCACHE.keys().next().value);return out;}
export const dbInvalidate=num=>{if(num)HCACHE.delete(num);else HCACHE.clear();};
/* ── part de l'affaire sur un chantier partagé (lot MU) : % saisi, sinon soudures du tracé de l'affaire / soudures de toutes les affaires du chantier ── */
export function partSite(a,id,ctx){const others=affAll().filter(x=>x.num!==a.num&&!x.deleted&&(x.sites||[]).includes(id)).map(x=>x.num);if(!others.length)return {k:1,shared:false,others:[]};
  const P=D(a).part||{};const man=P[id];if(man!==undefined&&man!==null&&man!==''&&isFinite(+man))return {k:Math.max(0,Math.min(100,+man))/100,shared:true,others,manual:true,pc:+man};
  const q=ctx&&ctx.traceQty?ctx.traceQty:null;const soud=num=>{if(!q)return 0;const AS=affState();const prev=AS.cur;AS.cur=num;try{const r=q(id);return r&&r.tot?+r.tot.soud||0:0;}catch(e){return 0;}finally{AS.cur=prev;}};
  const mine=soud(a.num);const tot=mine+others.reduce((s,n)=>s+soud(n),0);if(tot>0)return {k:mine/tot,shared:true,others,mine,tot,pc:Math.round(1000*mine/tot)/10};
  return {k:1/(others.length+1),shared:true,others,equal:true,pc:Math.round(1000/(others.length+1))/10};}
/* ── facturé par mois : situations mensuelles a.fact (reporting) ; un mois vide prend les situations déposées / payées du suivi de facturation ── */
export function factMois(a){const f=a.fact||{};const M={};const S={};(a.situations||[]).forEach(s=>{if(!s||s.deleted||!['depot','paye'].includes(s.etape)||!/^\d{4}-\d{2}$/.test(String(s.mois||''))||!isFinite(+s.montant)||!+s.montant)return;S[s.mois]=(S[s.mois]||0)+(+s.montant);});
  Object.keys(f).forEach(k=>{if(/^\d{4}-\d{2}$/.test(k)&&f[k]!==''&&f[k]!==null&&isFinite(+f[k]))M[k]=+f[k];});Object.keys(S).forEach(k=>{if(M[k]===undefined)M[k]=S[k];});return M;}
/* ── bons de commande et notes de frais de l'affaire ── */
const cmdTotal=c=>CMD&&CMD.cmdTotal?CMD.cmdTotal(c):(c.lignes||[]).reduce((s,l)=>s+(+l.qte||0)*(+l.pu||0),0);
export function bonsAffaire(a){const sites=new Set(a.sites||[]);const all=CMD&&CMD.cmdAll?CMD.cmdAll():regAll('commande').filter(c=>c&&c.num);return all.filter(c=>c&&!c.deleted&&(c.affaire===a.num||(!c.affaire&&c.site&&sites.has(c.site))));}
export const bonMontant=c=>c.etat==='facturee'&&c.facture&&isFinite(+c.facture.montant)&&+c.facture.montant>0?+c.facture.montant:r2(cmdTotal(c));
const BC_COMPTE=['envoyee','recue','facturee']; /* un brouillon n'est pas engagé, un bon annulé ne compte pas */
export function fraisAffaire(a){const sites=new Set(a.sites||[]);const all=CMD&&CMD.dbAll?CMD.dbAll():regAll('debours').filter(d=>d&&d.date);return all.filter(d=>d&&!d.deleted&&d.site&&sites.has(d.site)&&d.etat!=='refuse');}
/* ── LE MODÈLE : tout ce qui coûte, ligne par ligne, avec son mois — puis filtré par période à l'affichage ── */
export function dbModel(a,ctx){const H=heuresAffaire(a);const PI=peopleIdx();const parts={};(a.sites||[]).forEach(id=>{parts[id]=partSite(a,id,ctx);});const tva=tvaOf(a);
  const mo=H.rows.map(r=>{const pi=PI.get(r.p)||unk(r.p);const t=tauxPoste(a,pi.poste);const k=parts[r.site]?parts[r.site].k:1;const hk=r2(r.h*k);return Object.assign({},r,{poste:pi.poste,name:pi.name,taux:t.h,src:t.src,k,hk,cout:r2(hk*t.h)});});
  const bons=bonsAffaire(a).map(c=>{const k=c.affaire===a.num||!parts[c.site]?1:parts[c.site].k;const m=bonMontant(c);return {c,num:c.num,ym:String(c.at||'').slice(0,7),etat:c.etat,compte:BC_COMPTE.includes(c.etat),k,montant:m,cout:BC_COMPTE.includes(c.etat)?r2(m*k):0};});
  const frais=fraisAffaire(a).map(d=>{const ok=d.etat==='valide'||d.etat==='rembourse';const ht=r2((+d.montant||0)/(1+tva/100));return {d,id:d.id,ym:String(d.date||'').slice(0,7),ok,ttc:+d.montant||0,ht,cout:ok?ht:0};});
  const lignes=lignesOf(a).map(l=>({l,id:l.id,ym:String(l.date||'').slice(0,7),type:DB_TYPES.some(t=>t[0]===l.type)?l.type:'autre',cout:r2(+l.montant||0)}));
  const fact=factMois(a);const avant=+a.cumulN1||0;
  return {a,mo,bons,frais,lignes,fact,avant,parts,tva,postes:[...new Set(mo.map(r=>r.poste))]};}
/* période : 'tout' | 'annee' (DS.y) | 'mois' (DS.m) → un mois AAAA-MM est-il dedans ? */
const perOf=()=>DS.per==='mois'?{k:'mois',m:DS.m,lab:ymTxt(DS.m)}:DS.per==='annee'?{k:'annee',y:String(DS.y),lab:'année '+DS.y}:{k:'tout',lab:'toute l\'affaire'};
const inPer=(ym,P)=>P.k==='tout'?true:P.k==='annee'?String(ym||'').startsWith(P.y):String(ym||'')===P.m;
/* les chiffres d'une période : facturé, débours par poste, marge, reste */
export function dbTotaux(M,P){P=P||perOf();const S=(L,k)=>r2(L.filter(x=>inPer(x.ym,P)).reduce((s,x)=>s+(+x[k]||0),0));const mo=S(M.mo,'cout');const moConf=r2(M.mo.filter(x=>inPer(x.ym,P)&&!x.ok).reduce((s,x)=>s+x.cout,0));const hConf=r2(M.mo.filter(x=>inPer(x.ym,P)&&!x.ok).reduce((s,x)=>s+x.hk,0));
  const ach=S(M.bons,'cout'),nf=S(M.frais,'cout');const typ=t=>r2(M.lignes.filter(x=>x.type===t&&inPer(x.ym,P)).reduce((s,x)=>s+x.cout,0));const st=typ('st'),loc=typ('loc'),aut=typ('autre');
  const deb=r2(mo+ach+nf+st+loc+aut);const fact=r2(Object.keys(M.fact).filter(k=>inPer(k,P)).reduce((s,k)=>s+M.fact[k],0)+(P.k==='tout'?M.avant:0));const marche=+M.a.montant||0;
  const h=r2(M.mo.filter(x=>inPer(x.ym,P)).reduce((s,x)=>s+x.hk,0));const sansTaux=M.mo.some(x=>inPer(x.ym,P)&&!(x.taux>0));
  return {fact,deb,mo,moConf,h,hConf,ach,nf,st,loc,aut,marge:r2(fact-deb),margePct:fact>0?100*(fact-deb)/fact:null,marche,reste:marche?r2(marche-fact):null,sansTaux,P};}
/* série mensuelle d'une année : facturé / débours (pour la courbe et le tableau des mois) */
function serieAnnee(M,y){return MOIS.map((m,i)=>{const ym=y+'-'+String(i+1).padStart(2,'0');const P={k:'mois',m:ym};const t=dbTotaux(M,P);return {ym,fact:t.fact,deb:t.deb,marge:t.marge};});}
/* ── l'onglet ── */
export function deboursTabHTML(a,canEdit,ctx){try{return tabHTML(a,canEdit,ctx);}catch(e){console.warn('débours',e);return `<div class="card"><div class="eq-s">Débours : erreur d'affichage (${esc(e&&e.message||e)}).</div></div>`;}}
function tabHTML(a,canEdit,ctx){const M=dbModel(a,ctx);const P=perOf();const T=dbTotaux(M,P);if(!DS.cy||DS.cyAff!==a.num){const ys=Object.keys(M.fact).concat(M.mo.map(x=>x.ym)).map(k=>+String(k).slice(0,4)).filter(y=>y>2000);DS.cy=ys.length?Math.max(...ys):+today().slice(0,4);DS.cyAff=a.num;} /* année de la courbe : la dernière avec quelque chose, par affaire */
  const tile=(cls,v,l,sub)=>`<div class="db-tile ${cls}"><b>${v}</b><small>${l}</small>${sub?`<div class="db-sub">${sub}</div>`:''}</div>`;
  const factV=T.fact>0?eur(T.fact):(T.marche?`<span class="db-gris">${eur(T.marche)}</span>`:'—');
  const tiles=`<div class="db-tiles">${tile(T.fact>0?'ok':'',factV,T.fact>0?'facturé HT · '+esc(P.lab):'rien de facturé · marché (repère)',T.fact>0&&T.marche?'marché '+eur(T.marche):'')}${tile('',eur(T.deb),'débours HT · '+esc(P.lab),T.moConf?`<span class="db-conf">dont ${eur(T.moConf)} de main-d'œuvre à confirmer</span>`:(T.sansTaux?'<span class="db-conf">⚠ un coût horaire manque</span>':''))}${tile(T.fact>0?(T.marge>=0?'ok':'bad'):'',T.fact>0?eur(T.marge):'—','marge (facturé − débours)',T.fact>0?(T.marge>=0?'':'⚠ ')+pct(T.marge,T.fact)+' du facturé':'en attente de facturation')}${tile(T.reste!==null&&T.reste>1?'warn':'',T.reste!==null?eur(T.reste):'—','reste à facturer (marché − facturé)',T.marche?nb(100*T.fact/T.marche)+' % facturé':'pas de montant de marché')}</div>`;
  const per=`<div class="db-per"><span class="dim" style="font-size:12px">Période</span><button class="chip${DS.per==='tout'?' active':''}" data-act="x" data-v="db|per|tout">Tout</button><button class="chip${DS.per==='annee'?' active':''}" data-act="x" data-v="db|per|annee">Année</button>${DS.per==='annee'?`<span class="db-nav"><button class="chip" data-act="x" data-v="db|y|${DS.y-1}" aria-label="Année précédente">‹</button><b>${DS.y}</b><button class="chip" data-act="x" data-v="db|y|${DS.y+1}" aria-label="Année suivante">›</button></span>`:''}<button class="chip${DS.per==='mois'?' active':''}" data-act="x" data-v="db|per|mois">Mois</button>${DS.per==='mois'?`<span class="db-nav"><button class="chip" data-act="x" data-v="db|m|${ymAdd(DS.m,-1)}" aria-label="Mois précédent">‹</button><b>${esc(ymTxt(DS.m))}</b><button class="chip" data-act="x" data-v="db|m|${ymAdd(DS.m,1)}" aria-label="Mois suivant">›</button></span>`:''}</div>`;const tools=`<div class="db-tools"><button class="btn sm" data-act="x" data-v="db|xls">⬇ Excel</button><button class="btn sm" data-act="x" data-v="db|print">🖨 Imprimer</button></div>`;
  const shared=Object.keys(M.parts).filter(id=>M.parts[id].shared);const sname=id=>{const s=(ctx.sites||[]).find(x=>x.id===id);return s?(s.name||id):id;};
  const partBox=shared.length?`<div class="okbox" style="margin:0 0 8px">${shared.map(id=>{const p=M.parts[id];return `🔗 Chantier partagé « ${esc(sname(id))} » (avec ${esc(p.others.join(', '))}) : seule la part de l'affaire compte — <b>${nbx(p.pc)} %</b> ${p.manual?'(saisie)':p.equal?'(parts égales : rien de tracé)':'(soudures du tracé : '+nb(p.mine)+' / '+nb(p.tot)+')'}${canEdit?` · <label class="db-inl">part % <input class="f db-pc" type="number" min="0" max="100" step="0.1" data-xin="db|part|${esc(id)}" value="${p.manual?esc(p.pc):''}" placeholder="${nbx(p.pc)}"></label>`:''}`;}).join('<br>')}</div>`:'';
  return `<div class="card db-head"><div class="db-top"><h3>💶 Débours de l'affaire <span class="hint">· facturé − débours = marge, par période</span></h3>${tools}</div>${per}${tiles}<div class="hint">Tout en HT. Facturé = situations mensuelles de l'onglet Facturation (+ situations déposées / payées) ; débours = main-d'œuvre pointée × coût horaire, bons de commande engagés, notes de frais validées (TTC → HT), sous-traitance, location, autres.</div></div>
    ${partBox}${chartCard(M)}${repartCard(T)}${moCard(a,M,T,canEdit,ctx)}${achatsCard(a,M,P,canEdit)}${fraisCard(a,M,P,canEdit)}${depCard(a,M,P,canEdit)}`;}
/* courbe mensuelle facturé / débours (SVG, 12 mois) + tableau des mois */
function chartCard(M){const y=DS.cy;const S=serieAnnee(M,y);const cur=today();const nM=String(y)<cur.slice(0,4)?12:String(y)>cur.slice(0,4)?0:+cur.slice(5,7); /* les mois à venir ne sont pas tracés */const SS=S.slice(0,nM);
  const narrow=typeof window!=='undefined'&&window.innerWidth<560;const W=narrow?Math.max(280,Math.min(720,window.innerWidth-62)):720,H=narrow?200:230,L=narrow?40:52,R=14,T=16,B=30;const max=Math.max(0,...SS.map(s=>Math.max(s.fact,s.deb)));const nice=v=>{const p=Math.pow(10,Math.floor(Math.log10(v)));const c=v/p;return (c<=1?1:c<=2?2:c<=2.5?2.5:c<=5?5:10)*p;};const top=max>0?nice(max*1.08):1000; /* année vide : axe 0 → 1 k€ */
  const x=i=>L+i*(W-L-R)/11;const yv=v=>T+(H-T-B)*(1-v/top);const pts=k=>SS.map((s,i)=>x(i).toFixed(1)+','+yv(s[k]).toFixed(1)).join(' ');const kE=v=>v>=1000?nb(v/1000,v>=10000?0:1)+' k€':nb(v)+' €';
  const grid=[0,.25,.5,.75,1].map(f=>`<line x1="${L}" x2="${W-R}" y1="${yv(top*f).toFixed(1)}" y2="${yv(top*f).toFixed(1)}" stroke="#e6e3da" stroke-width="1"/><text x="${L-5}" y="${(yv(top*f)+3.5).toFixed(1)}" text-anchor="end" font-size="${narrow?9.5:10}" fill="#766f6f">${kE(top*f)}</text>`).join('');
  const dots=k=>SS.map((s,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${yv(s[k]).toFixed(1)}" r="4" fill="${k==='fact'?'#2563c7':'#e8501c'}" stroke="#fff" stroke-width="2"><title>${MOIS[i]} ${y} · ${k==='fact'?'facturé':'débours'} ${eur(s[k])}</title></circle>`).join('');
  const lastI=k=>{let j=-1;SS.forEach((s,i)=>{if(s[k]>0)j=i;});return j;};const lab=(k,dy)=>{const j=lastI(k);if(j<0)return '';const right=x(j)>W*0.7;const yj=yv(SS[j][k]),yp=right&&j>0?yv(SS[j-1][k]):yj;const yy=dy<0?Math.min(yj,yp):Math.max(yj,yp); /* à gauche du point : au-dessus / au-dessous du segment, pas dessus */return `<text x="${(x(j)+(right?-7:7)).toFixed(1)}" y="${(yy+dy).toFixed(1)}" font-size="${narrow?10:10.5}" font-weight="700" fill="#221f1f"${right?' text-anchor="end"':''}>${k==='fact'?'facturé':'débours'} ${kE(SS[j][k])}</text>`;};
  const mLab=i=>narrow?MOIS[i].slice(0,1):MOIS[i];
  const svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Facturé et débours par mois, ${y}">${grid}${MOIS.map((m,i)=>`<text x="${x(i).toFixed(1)}" y="${H-B+15}" text-anchor="middle" font-size="${narrow?10:10.5}" fill="${i<nM?'#766f6f':'#c4c0b8'}">${mLab(i)}</text>`).join('')}${SS.length?`<polyline points="${pts('fact')}" fill="none" stroke="#2563c7" stroke-width="2" stroke-linejoin="round"/><polyline points="${pts('deb')}" fill="none" stroke="#e8501c" stroke-width="2" stroke-linejoin="round"/>${dots('fact')}${dots('deb')}${lab('fact',-9)}${lab('deb',14)}`:`<text x="${W/2}" y="${H/2}" text-anchor="middle" font-size="12" fill="#766f6f">année à venir</text>`}</svg>`;
  const tot=S.reduce((o,s)=>({fact:o.fact+s.fact,deb:o.deb+s.deb}),{fact:0,deb:0});
  const rows=S.map((s,i)=>s.fact||s.deb?`<tr><td>${MOIS[i]} ${y}</td><td class="num">${s.fact?eur(s.fact):'—'}</td><td class="num">${s.deb?eur(s.deb):'—'}</td><td class="num ${s.marge<0?'db-neg':''}">${s.fact||s.deb?eur(s.marge):'—'}</td><td class="num">${s.fact>0?pct(s.marge,s.fact):'—'}</td></tr>`:'').join('');
  return `<div class="card db-chart"><h3>Facturé / débours par mois <span class="hint">· ${y}</span></h3><div class="db-per"><span class="db-nav"><button class="chip" data-act="x" data-v="db|cy|${y-1}" aria-label="Année précédente">‹</button><b>${y}</b><button class="chip" data-act="x" data-v="db|cy|${y+1}" aria-label="Année suivante">›</button></span><span class="db-leg"><span><i style="background:#2563c7"></i>facturé</span><span><i style="background:#e8501c"></i>débours</span></span></div>${svg}
    <details class="db-det"${DS.open.mois?' open':''}><summary class="dim">Le tableau des mois ${y} · facturé ${eur(tot.fact)} · débours ${eur(tot.deb)}</summary><div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Mois</th><th class="num">Facturé</th><th class="num">Débours</th><th class="num">Marge</th><th class="num">%</th></tr>${rows||'<tr><td colspan="5" class="dim">Rien sur cette année.</td></tr>'}</table></div></details></div>`;}
/* répartition par poste de débours */
function repartCard(T){const L=[['Main-d\'œuvre (heures pointées × coût horaire)',T.mo],['Achats (bons de commande engagés)',T.ach],['Notes de frais validées (HT)',T.nf],['Sous-traitance',T.st],['Location',T.loc],['Autres dépenses',T.aut]];
  return `<div class="card"><h3>Détail des débours <span class="hint">· ${esc(T.P.lab)}</span></h3><div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Poste de débours</th><th class="num">Montant HT</th><th class="num">Part</th></tr>${L.map(([l,v])=>`<tr><td>${l}</td><td class="num">${v?eur(v):'—'}</td><td class="num">${v?pct(v,T.deb):'—'}</td></tr>`).join('')}<tr class="tot"><td>Total débours</td><td class="num">${eur(T.deb)}</td><td class="num">100 %</td></tr></table></div></div>`;}
/* main-d'œuvre : coûts horaires, par personne, par mois, par chantier */
function moCard(a,M,T,canEdit,ctx){const P=T.P;const rows=M.mo.filter(x=>inPer(x.ym,P));const sname=id=>{const s=(ctx.sites||[]).find(x=>x.id===id);return s?(s.name||id):id;};
  const by=(key,lab)=>{const g={};rows.forEach(r=>{const k=key(r);(g[k]=g[k]||{k,lab:lab(r),h:0,hc:0,cout:0,cc:0,n:0}).h=r2(g[k].h+r.hk);if(!r.ok){g[k].hc=r2(g[k].hc+r.hk);g[k].cc=r2(g[k].cc+r.cout);}g[k].cout=r2(g[k].cout+r.cout);g[k].n++;});return Object.values(g);};
  const pers=by(r=>r.p,r=>r).sort((x,y)=>y.cout-x.cout||x.lab.name.localeCompare(y.lab.name,'fr'));const mois=by(r=>r.ym,r=>r.ym).sort((x,y)=>x.k<y.k?-1:1);const chant=by(r=>r.site,r=>r.site);
  const postes=[...new Set(M.mo.map(r=>r.poste))].sort((x,y)=>posteLab(x).localeCompare(posteLab(y),'fr'));const tx=D(a).taux||{};
  const taux=postes.length&&canEdit?`<div class="eq-lab">Coût horaire par poste <span class="hint">· base de prix (taux + frais généraux + sinistre) ; modifiable pour cette affaire</span></div><div class="db-taux">${postes.map(p=>{const t=tauxPoste(a,p);const base=(()=>{const T0=Object.assign({},D(a),{taux:{}});return tauxPoste(Object.assign({},a,{debours:T0}),p);})();return `<label class="db-tx${t.h>0?'':' miss'}"><span>${esc(posteLab(p))}${t.src==='base'?' <small>base de prix</small>':t.src==='affaire'?' <small>taux de l\'affaire'+(base.h>0?' (base : '+nb(base.h,2)+')':'')+'</small>':' <small class="db-conf">pas dans la base de prix : à renseigner</small>'}</span>${canEdit?`<span class="db-inl"><input class="f" type="number" min="0" step="0.01" data-xin="db|taux|${esc(p)}" value="${tx[p]!==undefined&&tx[p]!==null&&tx[p]!==''?esc(tx[p]):''}" placeholder="${base.h>0?nb(base.h,2):'€/h'}"> €/h</span>`:`<b>${t.h>0?nb(t.h,2)+' €/h':'—'}</b>`}</label>`;}).join('')}</div>`:'';
  const cols=canEdit?4:3;const tPers=pers.length?`<div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Personne</th><th class="txt">Poste</th><th class="num">Heures</th>${canEdit?'<th class="num">Coût HT</th>':''}</tr>${pers.map(g=>`<tr><td>${esc(g.lab.name)}</td><td class="dim txt">${esc(posteLab(g.lab.poste))}${canEdit&&!(g.lab.taux>0)?' <span class="db-conf">⚠ taux</span>':''}</td><td class="num">${hh(g.h)}${g.hc?`<div class="db-conf" style="font-size:10.5px">dont ${hh(g.hc)} à confirmer</div>`:''}</td>${canEdit?`<td class="num">${eur(g.cout)}${g.cc?`<div class="db-conf" style="font-size:10.5px">dont ${eur(g.cc)}</div>`:''}</td>`:''}</tr>`).join('')}<tr class="tot"><td colspan="2">Total</td><td class="num">${hh(T.h)}${T.hConf?`<div class="db-conf" style="font-size:10.5px">dont ${hh(T.hConf)} à confirmer</div>`:''}</td>${canEdit?`<td class="num">${eur(T.mo)}</td>`:''}</tr></table></div>`:'<div class="eq-s">Aucune heure pointée sur les chantiers de l\'affaire pour cette période.</div>';
  const tMois=mois.length>1?`<div class="eq-lab">Par mois</div><div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Mois</th><th class="num">Heures</th>${canEdit?'<th class="num">Coût HT</th>':''}</tr>${mois.map(g=>`<tr><td>${esc(ymTxt(g.k))}</td><td class="num">${hh(g.h)}${g.hc?` <span class="db-conf" style="font-size:10.5px">(${hh(g.hc)} à confirmer)</span>`:''}</td>${canEdit?`<td class="num">${eur(g.cout)}</td>`:''}</tr>`).join('')}</table></div>`:'';
  const tChant=chant.length>1||(a.sites||[]).length>1?`<div class="eq-lab">Par chantier</div><div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Chantier</th><th class="num">Part</th><th class="num">Heures comptées</th>${canEdit?'<th class="num">Coût HT</th>':''}</tr>${chant.map(g=>`<tr><td>${esc(sname(g.k))}</td><td class="num">${M.parts[g.k]&&M.parts[g.k].shared?nbx(M.parts[g.k].pc)+' %':'100 %'}</td><td class="num">${hh(g.h)}</td>${canEdit?`<td class="num">${eur(g.cout)}</td>`:''}</tr>`).join('')}</table></div>`:'';
  return `<div class="card"><h3>Main-d'œuvre <span class="hint">· ${esc(P.lab)} · ${hh(T.h)}${canEdit?' · '+eur(T.mo):''}</span></h3>${taux}${tPers}${tMois}${tChant}<div class="hint" style="margin-top:6px">Heures = celles de la navette de paie (pointages, semaine du lundi au samedi), rangées au mois civil du jour pointé, sur les chantiers liés à l'affaire (onglet Tracé &amp; chantiers). Un pointage pas encore validé compte « à confirmer » (dans le total, grisé).${canEdit?'':' Les coûts horaires et les montants de main-d\'œuvre sont réservés au bureau (droit « Affaires : créer et modifier »).'}</div></div>`;}
/* achats : bons de commande de l'affaire */
const BC_LAB=k=>{const E=(CMD&&CMD.BC_ETATS)||[];const e=E.find(x=>x[0]===k);return e?`<span class="af-tag" style="background:${e[2]}">${esc(e[1])}</span>`:esc(k||'');};
function achatsCard(a,M,P,canEdit){const L=M.bons.filter(b=>inPer(b.ym,P)).sort((x,y)=>String(y.c.at||'').localeCompare(String(x.c.at||'')));const tot=r2(L.reduce((s,b)=>s+b.cout,0));
  const rows=L.map(b=>{const c=b.c;return `<tr class="${b.compte?'':'db-off'}"><td><button class="lnk" data-act="x" data-v="db|bcopen|${esc(c.num)}">${esc(c.num)}</button><div class="dim" style="font-size:11px">${dFR(c.at)}</div></td><td class="txt">${esc(c.fournisseur||'fournisseur ?')}<div class="dim" style="font-size:11px">${esc(c.objet||'')}${c.affaire?'':' · <span class="db-conf">sans n° d\'affaire (chantier)</span>'}</div></td><td class="txt">${BC_LAB(c.etat)}${c.livraison?`<div class="dim" style="font-size:11px">livr. ${dFR(c.livraison)}</div>`:''}</td><td class="num ph">${eur2(cmdTotal(c))}</td><td class="num ph">${c.etat==='facturee'?eur2(bonMontant(c)):'—'}${b.k!==1&&b.compte?`<div class="dim" style="font-size:11px">part ${nbx(100*b.k)} %</div>`:''}</td><td class="num"><b>${b.compte?eur2(b.cout):'<span class="dim">non compté</span>'}</b></td><td>${canEdit&&c.etat!=='facturee'&&c.etat!=='annulee'?`<button class="btn sm" data-act="x" data-v="db|bcfact|${esc(c.num)}">✓ Facturé</button>`:''}</td></tr>`;}).join('');
  return `<div class="card"><h3>Achats <span class="hint">· bons de commande · ${esc(P.lab)} · ${eur(tot)}</span></h3>${canEdit?`<div class="eq-acts db-acts" style="margin:0 0 8px"><button class="btn primary" data-act="x" data-v="db|bcnew">＋ Bon de commande</button></div>`:''}${L.length?`<div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>N°</th><th class="txt">Fournisseur · objet</th><th class="txt">État</th><th class="num ph">Total HT</th><th class="num ph">Facturé HT</th><th class="num">Compté</th><th></th></tr>${rows}<tr class="tot"><td colspan="3">Total achats comptés</td><td class="ph" colspan="2"></td><td class="num">${eur2(tot)}</td><td></td></tr></table></div>`:'<div class="eq-s">Aucun bon de commande rattaché à l\'affaire (ni à ses chantiers) sur cette période.</div>'}<div class="hint" style="margin-top:6px">Un bon compte dès qu'il est envoyé (engagé) : total HT du bon, ou le montant de la facture quand il est marqué facturé. Brouillons et bons annulés sont affichés mais non comptés. « ＋ Bon de commande » ouvre l'écran des bons (Chantiers → Bons de commande), pré-rempli avec l'affaire et son chantier.</div></div>`;}
/* notes de frais des chantiers de l'affaire */
const NAT_LAB=k=>{const N=(CMD&&CMD.NATURES)||[];const e=N.find(x=>x[0]===k);return e?e[1]:(k||'');};
const NF_LAB=k=>{const E=(CMD&&CMD.DB_ETATS)||[];const e=E.find(x=>x[0]===k);return e?`<span class="af-tag" style="background:${e[2]}">${esc(e[1])}</span>`:esc(k||'');};
function fraisCard(a,M,P,canEdit){const L=M.frais.filter(f=>inPer(f.ym,P)).sort((x,y)=>String(y.d.date).localeCompare(String(x.d.date)));const ok=L.filter(f=>f.ok),att=L.filter(f=>!f.ok);const tot=r2(ok.reduce((s,f)=>s+f.ht,0));const tva=M.tva;
  const row=f=>`<tr class="${f.ok?'':'db-off'}"><td>${dFR(f.d.date)}</td><td class="txt">${esc(f.d.name||f.d.key||'')}</td><td class="txt">${esc(NAT_LAB(f.d.nature))}${f.d.commentaire?`<div class="dim" style="font-size:11px">${esc(f.d.commentaire)}</div>`:''}</td><td class="txt">${NF_LAB(f.d.etat)}</td><td class="num ph">${eur2(f.ttc)}</td><td class="num"><b>${eur2(f.ht)}</b></td></tr>`;
  return `<div class="card"><h3>Notes de frais <span class="hint">· ${esc(P.lab)} · ${eur(tot)} HT</span></h3><div class="db-inl" style="margin:0 0 6px"><span class="dim" style="font-size:12px">Les notes de frais sont saisies TTC : ramenées en HT avec une TVA de</span>${canEdit?`<input class="f db-pc" type="number" min="0" max="100" step="0.1" data-xin="db|tva" value="${esc(tva)}">`:`<b>${nb(tva,1)}</b>`}<span class="dim" style="font-size:12px">% (20 % d'office).</span></div>
    ${L.length?`<div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Date</th><th class="txt">Qui</th><th class="txt">Nature</th><th class="txt">État</th><th class="num ph">TTC</th><th class="num">HT</th></tr>${ok.map(row).join('')}<tr class="tot"><td colspan="4">Total validées (comptées)</td><td class="ph"></td><td class="num">${eur2(tot)}</td></tr>${att.length?`<tr><td colspan="6" class="dim" style="text-align:left">En attente de validation (non comptées) : ${att.length}</td></tr>${att.map(row).join('')}`:''}</table></div>`:'<div class="eq-s">Aucune note de frais sur les chantiers de l\'affaire pour cette période.</div>'}<div class="hint" style="margin-top:6px">Une note de frais compte quand elle est validée (ou remboursée) ; celles « saisies » attendent la validation (Chantiers → Notes de frais).</div></div>`;}
/* sous-traitance, location, autres : dépenses saisies dans l'onglet */
function depCard(a,M,P,canEdit){const L=M.lignes.filter(l=>inPer(l.ym,P)).sort((x,y)=>String(y.l.date||'').localeCompare(String(x.l.date||'')));const tot=r2(L.reduce((s,l)=>s+l.cout,0));const typ=k=>(DB_TYPES.find(t=>t[0]===k)||DB_TYPES[2])[1];
  const rows=L.map(x=>{const l=x.l;return `<tr><td>${dFR(l.date)}</td><td class="txt ph">${esc(typ(x.type))}</td><td class="txt">${esc(l.lib||'')}${l.com?`<div class="dim" style="font-size:11px">${esc(l.com)}</div>`:''}${l.pj&&l.pj.name?`<div style="font-size:11px">${l.pj.url?`<a href="${esc(l.pj.url)}" target="_blank" rel="noopener">📎 ${esc(l.pj.name)}</a>`:'📎 '+esc(l.pj.name)+' <span class="db-conf">(non envoyée : hors connexion, à redéposer)</span>'}</div>`:''}</td><td class="txt">${esc(l.fournisseur||'')}</td><td class="num"><b>${eur2(l.montant)}</b></td><td class="dim txt ph" style="font-size:11px">${esc(l.by||'')}</td><td style="white-space:nowrap">${canEdit?`<button class="btn sm" data-act="x" data-v="db|ledit|${esc(l.id)}" title="Modifier">✎</button> <button class="btn sm" data-act="x" data-v="db|lrm|${esc(l.id)}" style="color:#9b2c22" title="Retirer">✕</button>`:''}</td></tr>`;}).join('');
  return `<div class="card"><h3>Sous-traitance, location, autres dépenses <span class="hint">· ${esc(P.lab)} · ${eur(tot)} HT</span></h3>${canEdit?`<div class="eq-acts db-acts" style="margin:0 0 8px"><button class="btn primary" data-act="x" data-v="db|lnew">＋ Dépense</button></div>`:''}${L.length?`<div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Date</th><th class="txt ph">Type</th><th class="txt">Libellé</th><th class="txt">Fournisseur</th><th class="num">Montant HT</th><th class="txt ph">Par</th><th></th></tr>${rows}<tr class="tot"><td colspan="3">Total</td><td class="ph"></td><td class="num">${eur2(tot)}</td><td class="ph"></td><td></td></tr></table></div>`:'<div class="eq-s">Aucune dépense saisie pour cette période.</div>'}<div class="hint" style="margin-top:6px">Une facture de sous-traitant, une location (engin, base vie) ou une autre dépense sans bon de commande se saisit ici (date, nature, fournisseur, montant HT, pièce jointe en option). Modifiable et supprimable par le bureau.</div></div>`;}
/* ── B2 · vue d'ensemble (Commerce → Reporting) : toutes les affaires en cours ── */
export function dbOverviewHTML(ctx){try{const L=affAll().filter(a=>!a.deleted&&['en_cours','a_debuter'].includes(a.etat));if(!L.length)return '';const P={k:'tout',lab:'toute l\'affaire'};
    const R=L.map(a=>{const M=dbModel(a,ctx);const T=dbTotaux(M,P);return {a,T,alert:T.deb>T.fact,key:T.fact>0?T.margePct:(T.deb>0?-1e9:1e9)};}).sort((x,y)=>x.key-y.key||String(x.a.num).localeCompare(String(y.a.num)));
    const tot=R.reduce((o,r)=>({fact:o.fact+r.T.fact,deb:o.deb+r.T.deb}),{fact:0,deb:0});const nAl=R.filter(r=>r.alert).length;
    return `<div class="card db-ov"><h3>💶 Débours des affaires en cours <span class="hint">· facturé − débours = marge · ${R.length} affaire${R.length>1?'s':''}${nAl?' · <span class="db-conf">'+nAl+' en alerte</span>':''}</span></h3><div style="overflow:auto"><table class="rc af-tab db-tab"><tr><th>Affaire</th><th class="num">Facturé</th><th class="num">Débours</th><th class="num">Marge</th><th class="num">%</th><th class="num">Reste à facturer</th></tr>${R.map(r=>{const T=r.T;const a=r.a;return `<tr class="${r.alert?'db-alert':''}"><td><button class="lnk" data-act="x" data-v="db|open|${esc(a.num)}">${esc(a.num)}</button> <span class="dim">${esc(a.nom||'')}</span>${r.alert?' <span class="eq-tag db-conf" title="les débours dépassent le facturé">⚠ débours &gt; facturé</span>':''}</td><td class="num">${T.fact?eur(T.fact):'—'}</td><td class="num">${T.deb?eur(T.deb):'—'}</td><td class="num ${T.marge<0?'db-neg':''}">${T.fact||T.deb?eur(T.marge):'—'}</td><td class="num">${T.fact>0?pct(T.marge,T.fact):'—'}</td><td class="num">${T.reste!==null?eur(T.reste):'—'}</td></tr>`;}).join('')}<tr class="tot"><td>Total</td><td class="num">${eur(tot.fact)}</td><td class="num">${eur(tot.deb)}</td><td class="num">${eur(tot.fact-tot.deb)}</td><td class="num">${pct(tot.fact-tot.deb,tot.fact)}</td><td></td></tr></table></div><div class="hint">Triées de la marge la plus faible à la plus forte (en % du facturé ; une affaire qui dépense sans avoir facturé passe en tête). Clic sur le numéro → l'onglet Débours de l'affaire.</div></div>`;}catch(e){console.warn('débours : vue d\'ensemble',e);return '';}}
/* ── actions (data-act="x" data-v="db|k|arg|…") ── */
const canWrite=ctx=>!!(ctx&&ctx.can&&ctx.can('affaires.edit')&&!(ctx.viewing&&ctx.viewing()));
const say=(ctx,t)=>{if(ctx&&ctx.toast)ctx.toast(t);else if(A&&A.toast)A.toast(t);};
const cur=()=>{const AS=affState();return AS.cur?affGet(AS.cur):null;};
function dbAct(v,el,me,ctx){try{dbAct_(v,el,me,ctx);}catch(e){console.warn('débours : action',v,e);say(ctx,'Débours : '+(e&&e.message||e));}}
function dbAct_(v,el,me,ctx){const [k,arg,arg2]=String(v).split('|');const a=cur();const rerender=()=>{if(ctx&&ctx.render)ctx.render();};const ro=()=>{say(ctx,'Lecture seule : droit « Affaires : créer et modifier » nécessaire');};
  switch(k){
    case 'per':DS.per=['tout','annee','mois'].includes(arg)?arg:'tout';if(DS.per==='mois'&&!/^\d{4}-\d{2}$/.test(DS.m))DS.m=today().slice(0,7);rerender();return;
    case 'y':DS.y=+arg||DS.y;rerender();return;case 'm':if(/^\d{4}-\d{2}$/.test(arg))DS.m=arg;rerender();return;case 'cy':DS.cy=+arg||DS.cy;rerender();return;
    case 'open':affOpen(arg,'debours');DS.cy=null;rerender();return;
    case 'bcopen':{if(!CMD||!CMD.cmdState)return;const cs=CMD.cmdState();if(ctx&&ctx.go)ctx.go('cmd');cs.cur=arg;cs.tab='cmdfiche';rerender();return;}
    case 'bcnew':{if(!a)return;if(!canWrite(ctx)){ro();return;}if(!CMD||!CMD.cmdNextNum){say(ctx,'Bons de commande indisponibles');return;}const num=CMD.cmdNextNum();regSet('commande',num,{num,etat:'brouillon',affaire:a.num,site:(a.sites||[])[0]||null,lignes:[{designation:'',qte:1,unite:'u',pu:''}],by:A.userName(),at:new Date().toISOString()});const cs=CMD.cmdState();if(ctx&&ctx.go)ctx.go('cmd');cs.cur=num;cs.tab='cmdfiche';rerender();say(ctx,'Bon '+num+' créé pour l\'affaire '+a.num+' — « ‹ Affaire » pour revenir');return;}
    case 'bcfact':{if(!a)return;if(!canWrite(ctx)){ro();return;}const c=regGet('commande',arg);if(!c)return;factModal(a,c,ctx);return;}
    case 'lnew':{if(!a)return;if(!canWrite(ctx)){ro();return;}depModal(a,null,ctx);return;}
    case 'ledit':{if(!a)return;if(!canWrite(ctx)){ro();return;}const l=lignesOf(a).find(x=>x.id===arg);if(l)depModal(a,l,ctx);return;}
    case 'lrm':{if(!a)return;if(!canWrite(ctx)){ro();return;}const l=lignesOf(a).find(x=>x.id===arg);if(!l)return;if(!confirm('Retirer la dépense « '+(l.lib||typLab(l.type))+' » ('+eur2(l.montant)+' HT) ?'))return;dbSave(a,{lignes:(D(affGet(a.num)||a).lignes||[]).map(x=>x&&x.id===arg?Object.assign({},x,{deleted:true,deletedAt:new Date().toISOString()}):x)});rerender();return;}
    case 'xls':{if(!a)return;exportXlsx(a,ctx,canWrite(ctx)).catch(e=>{console.warn(e);say(ctx,'Export impossible : '+(e&&e.message||e));});return;}
    case 'print':{if(!a)return;const w=window.open('','_blank');if(!w){say(ctx,'Autorise la fenêtre pop-up pour imprimer');return;}w.document.write(printHTML(a,ctx,canWrite(ctx)));w.document.close();return;}
    case 'fold':DS.open[arg]=!DS.open[arg];rerender();return;
    default:return;}}
const typLab=k=>(DB_TYPES.find(t=>t[0]===k)||DB_TYPES[2])[1];
/* ── champs (data-xin="db|champ|arg") ── */
function dbInput(champ,el,me,ctx){const [k,arg]=String(champ).split('|');const a=cur();if(!a)return;if(!canWrite(ctx)){say(ctx,'Lecture seule : droit « Affaires : créer et modifier » nécessaire');if(ctx&&ctx.render)ctx.render();return;}
  const v=String(el.value||'').replace(',','.').trim();const n=v===''?null:(isFinite(+v)?+v:null);
  if(k==='taux'){const T=Object.assign({},D(affGet(a.num)||a).taux||{});if(n===null||!(n>0))delete T[arg];else T[arg]=Math.round(n*100)/100;dbSave(a,{taux:T});}
  else if(k==='tva'){dbSave(a,{tva:n===null||n<0?null:Math.round(n*10)/10});}
  else if(k==='part'){const P=Object.assign({},D(affGet(a.num)||a).part||{});if(n===null||n<0)delete P[arg];else P[arg]=Math.max(0,Math.min(100,Math.round(n*10)/10));dbSave(a,{part:P});}
  else return;if(ctx&&ctx.render)ctx.render();}
/* ── fenêtres : marquer un bon facturé (montant de la facture), saisir / modifier une dépense ── */
function factModal(a,c,ctx){const tot=r2(cmdTotal(c));A.openModal(`<div class="db-modal"><h3 style="margin-top:0">Bon ${esc(c.num)} facturé <span class="hint">· ${esc(c.fournisseur||'')}</span></h3><div class="eq-s" style="margin:0 0 8px">Total du bon : <b>${eur2(tot)} HT</b>. Si la facture du fournisseur est différente, mets son montant : c'est lui qui comptera dans les débours.</div>
    <label class="f">Montant de la facture € HT</label><input class="f" id="dbf-m" type="number" step="0.01" min="0" value="${esc(c.facture&&c.facture.montant?c.facture.montant:tot)}"><label class="f">N° de facture <span class="dim">(option)</span></label><input class="f" id="dbf-n" value="${esc(c.facture&&c.facture.num||'')}" placeholder="FA-…">
    <div class="actions" style="margin-top:10px"><button class="btn primary block" id="dbf-ok">✓ Marquer facturé</button><button class="btn block" data-close>Annuler</button></div></div>`);
  const ok=document.getElementById('dbf-ok');if(ok)ok.onclick=()=>{const m=parseFloat(String((document.getElementById('dbf-m')||{}).value||'').replace(',','.'));if(!(m>=0)){say(ctx,'Le montant');return;}const num=String((document.getElementById('dbf-n')||{}).value||'').trim();regSet('commande',c.num,{etat:'facturee',facture:{montant:Math.round(m*100)/100,num:num||null,at:new Date().toISOString(),by:A.userName()}});A.closeModal();say(ctx,c.num+' marqué facturé · '+eur2(m)+' HT');if(ctx&&ctx.render)ctx.render();};}
function depModal(a,l,ctx){const L=l||{};const td=today();A.openModal(`<div class="db-modal"><h3 style="margin-top:0">${l?'Modifier la dépense':'Nouvelle dépense'} <span class="hint">· affaire ${esc(a.num)}</span></h3>
    <div class="row db-form"><div><label class="f">Date</label><input class="f" id="dbd-date" type="date" value="${esc(L.date||td)}"></div><div><label class="f">Nature</label><select class="f" id="dbd-type">${DB_TYPES.map(t=>`<option value="${t[0]}"${(L.type||'st')===t[0]?' selected':''}>${t[1]}</option>`).join('')}</select></div><div><label class="f">Montant € HT</label><input class="f" id="dbd-m" type="number" step="0.01" min="0" value="${esc(L.montant!==undefined&&L.montant!==null?L.montant:'')}" placeholder="0,00"></div></div>
    <label class="f">Libellé</label><input class="f" id="dbd-lib" value="${esc(L.lib||'')}" placeholder="ex. terrassement tranchée rue des Essais"><label class="f">Fournisseur / sous-traitant</label><input class="f" id="dbd-f" value="${esc(L.fournisseur||'')}">
    <label class="f">Pièce jointe <span class="dim">(facture, devis — option)</span></label><div class="eq-acts" style="margin:0"><label class="btn">📎 ${L.pj&&L.pj.name?'Remplacer':'Joindre'} un fichier<input type="file" id="dbd-pj" accept="image/*,application/pdf" style="display:none"></label><span id="dbd-pjn" class="dim" style="align-self:center;font-size:12px">${L.pj&&L.pj.name?esc(L.pj.name):''}</span></div>
    <label class="f">Commentaire</label><input class="f" id="dbd-com" value="${esc(L.com||'')}">
    <div class="actions" style="margin-top:10px"><button class="btn primary block" id="dbd-ok">${l?'Enregistrer':'Ajouter la dépense'}</button><button class="btn block" data-close>Annuler</button></div></div>`);
  let PJ=L.pj||null;let busy=false;const inp=document.getElementById('dbd-pj');if(inp)inp.onchange=async()=>{const f=inp.files&&inp.files[0];inp.value='';if(!f)return;if(f.size>20*1024*1024){say(ctx,'Fichier trop gros (20 Mo max)');return;}busy=true;const lab=document.getElementById('dbd-pjn');if(lab)lab.textContent='⏳ envoi de '+f.name+'…';let url=null;try{url=A.sync&&A.sync.uploadDoc?await A.sync.uploadDoc('aff_'+String(a.num).replace(/[^A-Za-z0-9_-]/g,'_'),'debours',f.name,f):null;}catch(e){url=null;}PJ={name:f.name,size:f.size,url:url||undefined};busy=false;if(lab)lab.textContent=f.name+(url?'':' (non envoyée : hors connexion — à redéposer plus tard)');};
  const ok=document.getElementById('dbd-ok');if(ok)ok.onclick=()=>{const g=id=>String((document.getElementById(id)||{}).value||'');const m=parseFloat(g('dbd-m').replace(',','.'));if(!(m>=0)||g('dbd-m').trim()===''){say(ctx,'Le montant HT');return;}if(!/^\d{4}-\d{2}-\d{2}$/.test(g('dbd-date'))){say(ctx,'La date');return;}if(!g('dbd-lib').trim()&&!g('dbd-f').trim()){say(ctx,'Un libellé ou un fournisseur');return;}if(busy){say(ctx,'Attends la fin de l\'envoi de la pièce');return;}
    const row=Object.assign({},L,{id:L.id||'L'+uid(),date:g('dbd-date'),type:g('dbd-type'),lib:g('dbd-lib').trim(),fournisseur:g('dbd-f').trim(),montant:Math.round(m*100)/100,com:g('dbd-com').trim()||null,pj:PJ||null},l?{editAt:new Date().toISOString(),editBy:A.userName()}:{at:new Date().toISOString(),by:A.userName()});
    const cur2=affGet(a.num)||a;const old=(D(cur2).lignes||[]);dbSave(a,{lignes:l?old.map(x=>x&&x.id===l.id?row:x):old.concat([row])});A.closeModal();say(ctx,(l?'Dépense modifiée':'Dépense ajoutée')+' · '+eur2(m)+' HT');if(ctx&&ctx.render)ctx.render();};}
/* ── export Excel (xlsx.js) ── */
async function exportXlsx(a,ctx,full){const M=dbModel(a,ctx);const P=perOf();const T=dbTotaux(M,P);const sname=id=>{const s=(ctx.sites||[]).find(x=>x.id===id);return s?(s.name||id):id;};const y=DS.cy||new Date().getFullYear();const S=serieAnnee(M,y);
  const syn=[['Affaire',a.num],['Nom',a.nom||''],['Client',a.client||''],['Période',P.lab],['Marché € HT',+a.montant||0],[],['Facturé HT',T.fact],['Débours HT',T.deb],['Marge HT',T.marge],['Marge %',T.fact>0?Math.round(10*T.margePct)/10:''],['Reste à facturer',T.reste===null?'':T.reste],[],['Poste de débours','Montant HT'],['Main-d\'œuvre',T.mo],['dont à confirmer',T.moConf],['Achats (bons de commande)',T.ach],['Notes de frais (HT)',T.nf],['Sous-traitance',T.st],['Location',T.loc],['Autres',T.aut],['Total débours',T.deb],[],['Mois '+y,'Facturé','Débours','Marge']].concat(S.map((s,i)=>[MOIS[i]+' '+y,s.fact,s.deb,s.marge]));
  const mo=[['Date','Personne','Poste','Chantier','Heures pointées','Part affaire','Heures comptées','Validé'].concat(full?['Coût horaire','Coût HT']:[]).concat(['Mois'])].concat(M.mo.filter(x=>inPer(x.ym,P)).sort((u,v)=>u.d<v.d?-1:u.d>v.d?1:u.name.localeCompare(v.name,'fr')).map(r=>[r.d,r.name,posteLab(r.poste),sname(r.site),r.h,Math.round(1000*r.k)/10,r.hk,r.ok?'oui':'à confirmer'].concat(full?[r.taux,r.cout]:[]).concat([r.ym]))); /* coûts horaires : bureau seulement */
  const bons=[['N°','Date','Fournisseur','Objet','État','Total HT','Facturé HT','Part','Compté HT']].concat(M.bons.filter(b=>inPer(b.ym,P)).map(b=>[b.num,String(b.c.at||'').slice(0,10),b.c.fournisseur||'',b.c.objet||'',b.etat||'',r2(cmdTotal(b.c)),b.c.etat==='facturee'?bonMontant(b.c):'',Math.round(1000*b.k)/10,b.cout]));
  const frais=[['Date','Qui','Nature','État','TTC','HT','Compté']].concat(M.frais.filter(f=>inPer(f.ym,P)).map(f=>[f.d.date,f.d.name||f.d.key||'',NAT_LAB(f.d.nature),f.d.etat||'',f.ttc,f.ht,f.ok?'oui':'non']));
  const dep=[['Date','Type','Libellé','Fournisseur','Montant HT','Commentaire','Par','Pièce']].concat(M.lignes.filter(l=>inPer(l.ym,P)).map(x=>[x.l.date,typLab(x.type),x.l.lib||'',x.l.fournisseur||'',x.cout,x.l.com||'',x.l.by||'',x.l.pj&&x.l.pj.url||'']));
  const name='Debours_'+String(a.num).replace(/[^A-Za-z0-9_-]/g,'_')+(P.k==='tout'?'':'_'+(P.k==='mois'?P.m:P.y));let blob,fn;
  try{const bytes=await makeXlsx([{name:'Synthèse',rows:syn,widths:[30,16,16,16]},{name:'Main-d\'œuvre',rows:mo,head:1,widths:[12,24,20,24,10,10,10,12,12,12,10]},{name:'Achats',rows:bons,head:1,widths:[12,12,24,30,12,12,12,8,12]},{name:'Notes de frais',rows:frais,head:1,widths:[12,22,22,12,10,10,8]},{name:'Dépenses',rows:dep,head:1,widths:[12,16,30,24,12,24,16,30]}]);blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});fn=name+'.xlsx';}
  catch(e){console.warn('xlsx',e);const q=v=>typeof v==='number'?String(v).replace('.',','):'"'+String(v??'').replace(/"/g,'""')+'"';blob=new Blob(['\ufeff'+syn.concat([[]],mo).map(r=>r.map(q).join(';')).join('\n')],{type:'text/csv;charset=utf-8'});fn=name+'.csv';}
  const u=URL.createObjectURL(blob);const el=document.createElement('a');el.href=u;el.download=fn;document.body.appendChild(el);el.click();el.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);}
/* ── impression A4 (charte SCR) ── */
function printHTML(a,ctx,full){const M=dbModel(a,ctx);const P=perOf();const T=dbTotaux(M,P);const sname=id=>{const s=(ctx.sites||[]).find(x=>x.id===id);return s?(s.name||id):id;};const y=DS.cy||new Date().getFullYear();const S=serieAnnee(M,y);
  const rows=M.mo.filter(x=>inPer(x.ym,P));const g={};rows.forEach(r=>{(g[r.p]=g[r.p]||{name:r.name,poste:r.poste,h:0,hc:0,cout:0}).h=r2(g[r.p].h+r.hk);if(!r.ok)g[r.p].hc=r2(g[r.p].hc+r.hk);g[r.p].cout=r2(g[r.p].cout+r.cout);});const pers=Object.values(g).sort((u,v)=>v.cout-u.cout);
  const bons=M.bons.filter(b=>inPer(b.ym,P)),frais=M.frais.filter(f=>inPer(f.ym,P)&&f.ok),dep=M.lignes.filter(l=>inPer(l.ym,P));
  const kpi=`<div class="kpi"><div><b>${T.fact>0?eur(T.fact):'—'}</b><span>facturé HT${T.fact>0?'':(T.marche?' · marché '+eur(T.marche):'')}</span></div><div><b>${eur(T.deb)}</b><span>débours HT${T.moConf?' · dont '+eur(T.moConf)+' à confirmer':''}</span></div><div><b class="${T.fact>0?(T.marge>=0?'ok':'ko'):''}">${T.fact>0?eur(T.marge):'—'}</b><span>marge${T.fact>0?' · '+pct(T.marge,T.fact):''}</span></div><div><b>${T.reste!==null?eur(T.reste):'—'}</b><span>reste à facturer</span></div></div>`;
  const body=kpi+`<h2>Détail des débours</h2><table><tr><th>Poste</th><th class="n">Montant HT</th><th class="n">Part</th></tr>${[['Main-d\'œuvre',T.mo],['Achats (bons de commande)',T.ach],['Notes de frais (HT)',T.nf],['Sous-traitance',T.st],['Location',T.loc],['Autres',T.aut]].map(([l,v])=>`<tr><td>${l}</td><td class="n">${eur(v)}</td><td class="n">${v?pct(v,T.deb):'—'}</td></tr>`).join('')}<tr><td><b>Total débours</b></td><td class="n"><b>${eur(T.deb)}</b></td><td class="n">100 %</td></tr></table>
    <h2>Facturé / débours par mois · ${y}</h2><table><tr><th>Mois</th><th class="n">Facturé</th><th class="n">Débours</th><th class="n">Marge</th></tr>${S.map((s,i)=>s.fact||s.deb?`<tr><td>${MOIS[i]} ${y}</td><td class="n">${s.fact?eur(s.fact):'—'}</td><td class="n">${s.deb?eur(s.deb):'—'}</td><td class="n">${eur(s.marge)}</td></tr>`:'').join('')||'<tr><td colspan="4">—</td></tr>'}</table>
    <h2>Main-d'œuvre · ${hh(T.h)} · ${eur(T.mo)}</h2><table><tr><th>Personne</th><th>Poste</th><th class="n">Heures</th><th class="n">à confirmer</th>${full?'<th class="n">Coût HT</th>':''}</tr>${pers.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(posteLab(p.poste))}</td><td class="n">${hh(p.h)}</td><td class="n">${p.hc?hh(p.hc):'—'}</td>${full?`<td class="n">${eur(p.cout)}</td>`:''}</tr>`).join('')||'<tr><td colspan="5">Aucune heure pointée.</td></tr>'}</table>
    <h2>Achats · bons de commande · ${eur(T.ach)}</h2><table><tr><th>N°</th><th>Fournisseur · objet</th><th>État</th><th class="n">Total HT</th><th class="n">Compté HT</th></tr>${bons.map(b=>`<tr><td>${esc(b.num)}</td><td>${esc(b.c.fournisseur||'')} · ${esc(b.c.objet||'')}</td><td>${esc(b.etat||'')}</td><td class="n">${eur2(cmdTotal(b.c))}</td><td class="n">${b.compte?eur2(b.cout):'non compté'}</td></tr>`).join('')||'<tr><td colspan="5">Aucun bon.</td></tr>'}</table>
    <h2>Notes de frais validées · ${eur(T.nf)} HT</h2><table><tr><th>Date</th><th>Qui</th><th>Nature</th><th class="n">TTC</th><th class="n">HT</th></tr>${frais.map(f=>`<tr><td>${dFR(f.d.date)}</td><td>${esc(f.d.name||'')}</td><td>${esc(NAT_LAB(f.d.nature))}</td><td class="n">${eur2(f.ttc)}</td><td class="n">${eur2(f.ht)}</td></tr>`).join('')||'<tr><td colspan="5">Aucune.</td></tr>'}</table>
    <h2>Sous-traitance, location, autres · ${eur(T.st+T.loc+T.aut)}</h2><table><tr><th>Date</th><th>Type</th><th>Libellé</th><th>Fournisseur</th><th class="n">Montant HT</th></tr>${dep.map(x=>`<tr><td>${dFR(x.l.date)}</td><td>${esc(typLab(x.type))}</td><td>${esc(x.l.lib||'')}</td><td>${esc(x.l.fournisseur||'')}</td><td class="n">${eur2(x.cout)}</td></tr>`).join('')||'<tr><td colspan="5">Aucune.</td></tr>'}</table>
    <div class="card soft">Heures = navette de paie (pointages, lundi → samedi), coût horaire = base de prix SCR (taux + frais généraux + sinistre) ou taux saisi pour l'affaire ; notes de frais TTC ramenées en HT (TVA ${nb(M.tva,1)} %) ; chantier partagé : part de l'affaire seulement.</div>`;
  return A.docHTML({title:'Débours — '+a.num,h1:'Débours · '+(a.nom||a.num),kicker:'Commerce · débours de l\'affaire · '+esc(a.num),sub:esc(a.client||'')+(a.ville?' · '+esc(a.ville):''),meta:[['Affaire',esc(a.num)],['Période',esc(P.lab)],['Marché HT',a.montant?eur(a.montant):'—'],['Chantiers',esc((a.sites||[]).map(sname).join(', ')||'—')]],body,css:'.kpi b.ok{color:var(--ok)}.kpi b.ko{color:var(--ko)}',footLeft:'SCR · commerce · débours'});}
/* ── CSS du lot (injectée : index.html n'est pas touché) ── */
function css(){try{if(typeof document==='undefined'||document.getElementById('css-lot-db'))return;const s=document.createElement('style');s.id='css-lot-db';s.textContent=`
.db-tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin:8px 0 6px}
.db-tile{background:var(--page,#f6f4ef);border:1px solid var(--line);border-radius:12px;padding:10px 12px;min-width:0}
.db-tile b{display:block;font-size:20px;line-height:1.1;letter-spacing:-.02em;overflow-wrap:anywhere}.db-tile small{display:block;font-size:11.5px;color:var(--ink2);line-height:1.2;margin-top:3px}
.db-tile.ok b{color:#15673a}.db-tile.bad b{color:#9b2c22}.db-tile.warn b{color:#7a5200}.db-tile .db-sub{font-size:11.5px;color:var(--muted);margin-top:3px}.db-gris{color:var(--muted);font-weight:600}
.db-top{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap}.db-top h3{flex:1 1 260px;margin:0}.db-tools{display:flex;gap:6px;flex:0 0 auto}.db-tools .btn.sm{min-height:36px}
.db-per{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:4px 0}.db-per .chip,.db-per .btn.sm{min-height:36px;cursor:pointer}.db-nav{display:inline-flex;align-items:center;gap:4px}.db-nav b{min-width:70px;text-align:center;font-size:13px}.db-nav .chip{min-width:36px;justify-content:center}
.db-chart svg{width:100%;height:auto;display:block;margin:4px 0}.db-leg{display:inline-flex;gap:14px;font-size:12px;color:var(--ink2)}.db-leg i{display:inline-block;width:14px;height:3px;border-radius:2px;vertical-align:middle;margin-right:5px}
.db-det summary{cursor:pointer;font-size:12.5px;min-height:34px;display:flex;align-items:center}
table.db-tab td.num,table.db-tab th.num{text-align:right;white-space:nowrap}table.db-tab td.txt,table.db-tab th.txt{text-align:left;white-space:normal}table.db-tab td:first-child,table.db-tab th:first-child{white-space:normal}table.db-tab td{vertical-align:top}table.db-tab tr.db-off td{color:var(--muted)}table.db-tab tr.db-alert td:first-child{background:#fdeae7}
.db-conf{color:#7a5200}.db-neg{color:#9b2c22}table.db-tab .lnk{display:inline-flex;align-items:center;min-height:34px;font-weight:700}
.db-taux{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:8px;margin:0 0 8px}.db-tx{display:flex;flex-direction:column;gap:4px;border:1px solid var(--line);border-radius:10px;padding:8px 10px;background:var(--page,#f6f4ef);font-size:12.5px}.db-tx small{display:block;color:var(--muted);font-size:11px}.db-tx.miss{border-color:#f0c76a;background:#fff8e6}
.db-inl{display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap}.db-inl input.f{width:96px;min-height:40px;padding:6px 8px;font-size:16px}.db-inl input.db-pc{width:84px} /* 16 px : pas de zoom iOS à la saisie */
.db-acts .btn{min-height:40px}.db-acts>*{flex:0 0 auto}
.db-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:6px}
.db-modal .btn{min-height:44px}.db-modal .actions{display:flex;flex-direction:column;gap:8px}.db-modal input.f,.db-modal select.f{min-height:44px}
@media (max-width:480px){.db-tiles{grid-template-columns:repeat(2,1fr)}.db-tile b{font-size:17px}.db-tools{flex:1 1 100%}.db-tools .btn.sm{flex:1 1 45%;min-height:40px}.db-chart svg{min-height:150px}table.db-tab .ph{display:none}}`;document.head.appendChild(s);}catch(e){}}
/* ── tests / outillage (window.TRACE.debours) ── */
export function dbTestApi(){const tctx=()=>({sites:(EC&&EC.sites)||[],traceQty:EC&&EC.api&&EC.api.traceQty?EC.api.traceQty:null});return {state:DS,model:num=>{const a=affGet(num);return a?dbModel(a,tctx()):null;},totaux:(num,P)=>{const a=affGet(num);return a?dbTotaux(dbModel(a,tctx()),P):null;},heures:num=>{const a=affGet(num);return a?heuresAffaire(a).rows:null;},invalidate:dbInvalidate,taux:(num,p)=>{const a=affGet(num);return a?tauxPoste(a,p):null;}};}
